      351: {
        title: "K'amara nk'Onye-nzọput'ayi,",
        number: 351,
        author: "Amaghị",
        composer: "Amaghị",
        tune: "May the grace of Christ, our Saviour.",
        meter: "8.7.8.7.8.7.8.7.",
        key: "Amaghị",
        scripture: "2 Ndi Kọrint 13. 14.",
        theme: "ABÙ NTÀ DI ICHE ICHE",
        year: "Amaghị",
        lyrics: [
          {
            verse: 1,
            text: [
              "K'amara nk'Onye-nzọput'ayi,",
              "Na ihu-n'anya nke Nna,",
              "Yere iru-ọma Mọ Nsọ,",
              "Si n'elu dikwasi ayi.",
              "Otú a k'ayi nile n'Onye-nw'ayi",
              "Bikọ nim'idi-n'otù;",
              "Nenwe ọṅu nime nnwekọ",
              "Nke uwa napugh inye. Amen."
            ]
          }
        ],
        history: "\"Ka amara nke Onye-nwe-ayi Jisus Kraist, na ihu-n'anya nke Chineke, na nnwekọ nke Mọ Nsọ, diyere unu nile.\""
      },
