      368: {
        title: "Nna nk'ihu-n'anya, Gi",
        number: 368,
        author: "Amaghị",
        composer: "Amaghị",
        tune: "Amaghị",
        meter: "6.4.6.4.D.",
        key: "(U. 41 (N.H.)).",
        scripture: "1 Jọn 5. 11.",
        theme: "CHINEKE NNA",
        year: "Amaghị",
        lyrics: [
          {
            verse: 1,
            text: [
              "Nna nk'ihu-n'anya, Gi",
              "B'Onye-nwe ndu;",
              "Gi pur'isi n'elu",
              "Nye ya ugbu a.",
              "Ndu nke di omimi,",
              "Bú ezi ndu;",
              "Ndu nke nadigide",
              "Mgb'ebigh-ebi."
            ]
          },
          {
            verse: 2,
            text: [
              "K'uch'ayi nadi ọhu",
              "Kwa-ubọchi;",
              "Sacha njọ zor'ezo,",
              "K'ayi ghar'ida.",
              "Ndu nke-Gi zur'ezù",
              "Di kwa ọhu;",
              "Site n'aka nke-Gi",
              "K'ayi nwe ngọzi."
            ]
          },
          {
            verse: 3,
            text: [
              "Nna nk'ihu-n'anya, me",
              "K'ayi namata",
              "Ka I si nakpọ ayi",
              "Kar'ihe dum:—",
              "K'ayi fe Gi ofùfe,",
              "Nekp'ekpere,",
              "Eb'ayi nwere ndu-Gi",
              "Nk'ebigh-ebi. Amen."
            ]
          }
        ],
        history: "\"Àmà ahu bu nka, na Chineke nyere ayi ndu ebigh-ebi, ndu ahu di nime Ọkpara-Ya.\""
      },
      369: {
        title: "Chineke bu Ony'Okike;",
        number: 369,
        author: "Amaghị",
        composer: "Amaghị",
        tune: "Amaghị",
        meter: "C.M.",
        key: "Amaghị",
        scripture: "Jenesis 1. 1.",
        theme: "CHINEKE NNA",
        year: "Amaghị",
        lyrics: [
          {
            verse: 1,
            text: [
              "Chineke bu Ony'Okike;",
              "O kere ihe dum;",
              "N'igwé nile n'uwa nile",
              "K'agahu ọlu-Ya."
            ]
          },
          {
            verse: 2,
            text: [
              "K'ayi gua ihe ole-n'ole",
              "N'etiti ọlu-Ya;",
              "N'ihi n'ebigh-ebi ezùgh",
              "Igukọ ha nile."
            ]
          },
          {
            verse: 3,
            text: [
              "Na mbu Ọ si, \"Ka ihè di\":",
              "Ma, le, ihè we di;",
              "O kere mbara el'igwe,",
              "Kè kwa al'akọrọ."
            ]
          },
          {
            verse: 4,
            text: [
              "O kere osisi nile",
              "Nke di nim'ok'ọhia,",
              "Yikwasi ha nma dik'uwe",
              "Na nkpuru d'ich'iche."
            ]
          },
          {
            verse: 5,
            text: [
              "Lekwasi anyanwu anya,",
              "Ọnwa, na kpakpando:",
              "I gatu egwu-Ya kari,",
              "Bú Chuku-Okike."
            ]
          },
          {
            verse: 6,
            text: [
              "O ker'anu nakpu akpu,",
              "N'an'ufe di n'elu;",
              "O kpub'ọlu-Ya okp'eze",
              "Site n'ikpu madu."
            ]
          },
          {
            verse: 7,
            text: [
              "Madu nka k'O yikwasiri",
              "Nghọta n'amam-ihe,",
              "Ka madu we me uche-Ya,",
              "Bú Onye kere ya."
            ]
          },
          {
            verse: 8,
            text: [
              "K'uwa rapu npako-ya, we",
              "Sọpuru Chineke,",
              "K'o we diri ya nma ugbu a,",
              "We rue mgb'ebigh-ebi. Amen."
            ]
          }
        ],
        history: "\"Na mbu Chineke kere elu-igwe na uwa.\""
      },
